# Reproduce selected published population-PK equations independently from model C++.
#
# The oracle below is analytical R mathematics transcribed from the PRIMARY
# publications. It does NOT use implementation-derived expected values, compiled
# source equations, model defaults, prior software snapshots, or an output CSV
# generated by the MIPD engine.
#
# Scope: typical fixed-effects concentration-time curves, not stochastic model
# reproduction, posterior MAP estimation, clinical validation or extrapolation.

suppressPackageStartupMessages(library(mrgsolve))

arguments <- commandArgs(trailingOnly = FALSE)
file_argument <- sub("^--file=", "", grep("^--file=", arguments, value = TRUE)[1])
APP_ROOT <- normalizePath(file.path(dirname(file_argument), ".."), winslash = "/", mustWork = TRUE)
source(file.path(APP_ROOT, "R", "model_library.R"), local = TRUE)

times <- c(0.5, 1, 4, 12, 24)
passed <- 0L

check_close <- function(actual, expected, label, rel_tol = 1e-5, abs_tol = 1e-7) {
  if (length(actual) != length(expected) || any(!is.finite(actual)) ||
      any(!is.finite(expected))) stop("Invalid oracle comparison: ", label)
  differences <- abs(unname(actual) - unname(expected))
  tolerance <- abs_tol + rel_tol * pmax(abs(expected), 1e-9)
  if (any(differences > tolerance)) {
    i <- which.max(differences / tolerance)
    stop(sprintf("%s: at position %d observed %.12g, source equation %.12g, difference %.4g (tolerance %.4g)",
                 label, i, actual[i], expected[i], differences[i], tolerance[i]))
  }
}

simulate_case <- function(id, scenario, params, amount, rate, expected_cl, expected_v,
                          predicted, volume_column) {
  # The implementation is used ONLY to obtain the values to be checked.
  model <- mrgsolve::zero_re(compile_model(model_id = id))
  model <- do.call(mrgsolve::param, c(list(model), params))
  route <- model_routes(model_record(id))[[1]]
  cmt <- match(model_administration_cmt(model_record(id), route), model@cmtL)
  stopifnot(length(cmt) == 1L, !is.na(cmt))

  result <- as.data.frame(mrgsolve::mrgsim(
    model, mrgsolve::ev(amt = amount, cmt = cmt, rate = rate),
    tgrid = times, obsonly = TRUE, recsort = 3,
    atol = 1e-12, rtol = 1e-12
  ))
  stopifnot(nrow(result) == length(times))
  # Check mechanistic parameters in addition to concentrations; otherwise a
  # compensating error in CL and V could conceivably conceal a mismatch.
  check_close(result$CL, rep(expected_cl, length(times)), paste(id, scenario, "CL"), rel_tol = 1e-9)
  check_close(result[[volume_column]], rep(expected_v, length(times)),
              paste(id, scenario, "V"), rel_tol = 1e-9)
  check_close(result$DV, predicted, paste(id, scenario, "C(t)"))
  cat("SOURCE EQUATION PASS ", id, " / ", scenario, "\n", sep = "")
  invisible(TRUE)
}

# Roberts et al., 2011, Antimicrob Agents Chemother 55:2704-2709
# DOI 10.1128/AAC.01708-10, equations 3/4, Table 2.
# One-compartment, IV constant-rate input. Measured urinary CRCL is normalized
# to 1.73 m2; WT is total body weight, with concentration in mg/L.
for (scenario in list(
  list(label = "reference", crcl = 90.7, wt = 74.8),
  list(label = "reduced renal function", crcl = 50, wt = 110),
  list(label = "augmented renal clearance", crcl = 140, wt = 55)
)) {
  cl <- 4.58 * scenario$crcl / 100          # L/h: published equation
  v <- 1.53 * scenario$wt                  # L: published equation
  dose <- 1000                             # mg: synthetic test input
  infusion_hours <- 24
  rate <- dose / infusion_hours            # mg/h
  oracle <- rate / cl * (-expm1(-cl * times / v))
  simulate_case(
    "vanco_roberts", scenario$label,
    list(CRCL = scenario$crcl, WT = scenario$wt),
    dose, rate, cl, v, oracle, "V"
  )
  passed <- passed + 1L
}

# Revilla et al., 2010, Br J Clin Pharmacol 70:201-212.
# DOI 10.1111/j.1365-2125.2010.03679.x, final covariate model, Table 4.
# Published CL is mL/min/kg. CRCL is measured over 24 h in mL/min:
# normalize by weight before applying the source formula, then convert
# 1 mL/min = 0.06 L/h. Serum creatinine source threshold: 1 mg/dL = 88.4 umol/L.
for (scenario in list(
  list(label = "creatinine at threshold", age = 61.1, crcl = 74.7, wt = 73, creat = 88.4),
  list(label = "creatinine above threshold", age = 61.1, crcl = 74.7, wt = 73, creat = 123.8),
  list(label = "older adult and higher CRCL", age = 80, crcl = 120, wt = 60, creat = 80)
)) {
  cl_ml_min_kg <- 0.67 * (scenario$crcl / scenario$wt) + scenario$age^(-0.24)
  cl <- cl_ml_min_kg * scenario$wt * 0.06  # L/h
  elevated <- as.integer(scenario$creat / 88.4 > 1)
  v <- 0.82 * (2.49^elevated) * scenario$wt # L
  dose <- 1000                             # mg: synthetic test input
  oracle <- dose / v * exp(-cl * times / v) # IV bolus closed-form solution
  simulate_case(
    "vanco_pkjust", scenario$label,
    list(AGE = scenario$age, CRCL = scenario$crcl,
         WT = scenario$wt, CREAT = scenario$creat),
    dose, 0, cl, v, oracle, "V1"
  )
  passed <- passed + 1L
}

stopifnot(passed == 6L)
cat(sprintf("Independent primary-source population-equation checks: %d scenarios, 2 models.\n", passed))
